def solve(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    line_col=[c for c in cnt if c!=bg and cnt[c]>h+w-2][0]  # line color (many)
    mark_col=[c for c in cnt if c!=bg and c!=line_col][0]
    rows=[i for i in range(h) if all(g[i][j]==line_col for j in range(w))]
    cols=[j for j in range(w) if all(g[i][j]==line_col for i in range(h))]
    mr,mc=[(i,j) for i in range(h) for j in range(w) if g[i][j]==mark_col][0]
    out=[r[:] for r in g]
    def ring(c):
        n=(h,c)
        for di in(-1,0,1):
            for dj in(-1,0,1):
                x,y=c[0]+di,c[1]+dj
                if 0<=x<h and 0<=y<w and (di,dj)!=(0,0):
                    out[x][y]=n if g[x][y]!=line_col else g[x][y]
    if rows:
        d=min(abs(r-mr) for r in rows)
        r0=rows[min(range(len(rows)),key=lambda i:abs(rows[i]-mr))]
        for j in range(min(mc,r0)): pass
        # nearest line row(s)
        cand=[r for r in rows if abs(r-mr)==d]
        for r in cand:
            c=r
            for k in range(min(mr,r)+1,max(mr,r)):
                out[k][mc]=mark_col
            ring((r,mc))
    if cols:
        d=min(abs(c-mc) for c in cols)
        cand=[c for c in cols if abs(c-mc)==d]
        for c in cand:
            r=c
            for k in range(min(mc,c)+1,max(mc,c)):
                out[mr][k]=mark_col
            ring((mr,c))
    return out

