    line_col=max(others,key=lambda c:cnt[c]); mark_col=[c for c in others if c!=line_col][0]
    rows=[i for i in range(h) if all(g[i][j]==line_col for j in range(w))]
    cols=[j for j in range(w) if all(g[i][j]==line_col for i in range(h))]
    pts=[(i,j) for i in range(h) for j in range(w) if g[i][j]==mark_col]
    out=[r[:] for r in g]
    def ring(r,c):
        for di in(-1,0,1):
            for dj in(-1,0,1):
                if di==dj==0: continue
                x,y=r+di,c+dj
                if 0<=x<h and 0<=y<w and out[x][y]!=line_col:
                    out[x][y]=line_col
    # choose orientation (horizontal lines or vertical lines); extend marker toward the nearest full line
    if rows:
        horz=True
    else:
        horz=False
    d0=min(abs(p[0]-rows[0]) for p in pts) if horz else min(abs(p[1]-cols[0]) for p in pts)
    # distance of each pt to the near line; pick the closest pair (pt,line); beam extends between them
    best=[]
    for p in pts:
        if horz:
            dr=min(abs(r-p[0]) for r in rows)
        else:
            dc=min(abs(c-p[1]) for c in cols)
        cand=[r for r in rows if abs(r-p[0])==dr] if horz else [c for c in cols if abs(c-p[1])==dc]
        best.append((p,dr,cand))
    best.sort(key=lambda t:t[1])
    p,dr,cand=best[0]
    if horz:
        r=cand[0]; mr,mc=p[0],p[1]
        lo,hi=min(mr,r)+1,max(mr,r)-1
        for k in range(lo,hi+1):
            out[k][mc]=mark_col
        ring(r,mc)
    else:
        c=cand[0]; mr,mc=p[0],p[1]
        lo,hi=min(mc,c)+1,max(mc,c)-1
        for k in range(lo,hi+1):
            out[mr][k]=mark_col
        ring(mr,c)
    return out

