    else:
        # treat both sets as lines (multi-orientation?) fall back
        lcolor=None
        LR,lcolor= [],None
        lcand=set()
        for r in lrows: lcand|=set(g[r])
        for c in lcols: lcand|=set(g[r][c] for r in range(h))
        lcolor=max((v for v in lcand if v!=bg), key=lambda v:cnt[v])
        LR=lrows; LC=lcols
    Lset={r for r in LR}|{c for c in LC}
    markers=[(r,c) for r in range(h) for c in range(w) if g[r][c]!=bg and g[r][c]!=lcolor]
    mc=markers[0][2] if False else None
    mcol=Counter(g[r][c] for r,c in markers).most_common(1)[0][0]
    o=[row[:] for row in g]
    for (r,c) in markers:
