                if g[r][cc]==lcolor: break
                o[r][cc]=mcol; cc+=dc
            if g[r][cc]==lcolor:
                o[r][cc]=mcol  # crossing cell
                for dr in (-1,1):
                    rr=r+dr
                    if 0<=rr<h:
                        for x in range(max(0,c-1),min(w,c+2)):
                            o[rr][x]=lcolor
        # horizontal lines: beam vertical
        for dr in (-1,1):
            rr=r+dr
            while 0<=rr<h and rr not in set(LR):
                if g[rr][c]==lcolor: break
                o[rr][c]=mcol; rr+=dr
            if g[rr][c]==lcolor:
